import asyncio
from django.http import HttpResponse
from django.test import RequestFactory
from django.views import View

class AsyncPostOnly(View):
    async def post(self, request):
        return HttpResponse("ok")

class SyncPostOnly(View):
    def post(self, request):
        return HttpResponse("ok")

rf = RequestFactory()
for cls, is_async in [(AsyncPostOnly, True), (SyncPostOnly, False)]:
    response = cls.as_view()(rf.get("/demo"))
    print(cls.__name__, "coroutine:", asyncio.iscoroutine(response), "expected:", is_async)
    if is_async:
        response = asyncio.run(response)
    print("  status:", response.status_code, "Allow:", response.headers["Allow"])
EOF","description":"Reproduce GET on async post-only view"}

